        public static string Mode(string name, bool dark) => "gear:" + name + ":" + (dark ? "dark" : "light");

        /// <summary>The palette for a "gear:name:dark|light" mode, or null when the mode is not one of them.</summary>
        public static UiPalette? Resolve(string mode)
        {
            if (!mode.StartsWith("gear:", StringComparison.Ordinal)) return null;
            var i = mode.LastIndexOf(':'); if (i <= 5) return null;
            var name = mode.Substring(5, i - 5); var dark = string.Equals(mode.Substring(i + 1), "dark", StringComparison.Ordinal);
            foreach (var e in All) if (e.Name == name) return dark ? e.Dark() : e.Light();
            return null;
        }
    }
